  }
  const throws=projectile._s3SupportCoolerThrows||[];
  for(let i=throws.length-1;i>=0;i--){const d=throws[i];d.age+=dt;d.prev.copy(d.pos);
    // EnergyStand.MoveParam, 11.3.0: source frames -> seconds. Preserve
    // native gravity-then-drag order; exponentiate retention for subframes.
    d.vel.y-=TACTICOOLER_SOURCE.flyGravity*3600*dt;
    d.vel.multiplyScalar(Math.pow(1-TACTICOOLER_SOURCE.flyPositionAirResist,60*dt));
    d.pos.addScaledVector(d.vel,dt);
    const hit=G.physics?.segment?.(d.prev,d.pos,d.hit);let landed=hit?.hit&&hit.normal.y>.4;
    if(hit?.hit){d.pos.copy(hit.point);if(!landed){d.pos.addScaledVector(hit.normal,.03);d.vel.addScaledVector(hit.normal,-d.vel.dot(hit.normal));}}
    const floor=G.level?.groundHeight?.(d.pos.x,d.pos.z);
    if(!landed&&Number.isFinite(floor)&&d.pos.y<=floor){d.pos.y=floor;landed=true;}
    if(landed){releaseVisual(d,G);throws.splice(i,1);deployCooler(d.owner,projectile,G,THREE,false,d.pos.toArray());}
    else if(d.age>5||!playing){releaseVisual(d,G);throws.splice(i,1);}
    else d.mesh?.position.copy(d.pos);
  }
  const coolers=projectile._s3SupportCoolers || [];
  for(let i=coolers.length-1;i>=0;i--) {
    const stand=coolers[i];
    advanceTowerStand(stand,G);
    if(G.time+TINY>=stand.expires||!playing) {endTacticoolerGauge(stand);releaseVisual(stand,G);coolers.splice(i,1);continue;}
    // Each actor's owner decides whether it obtained a drink; remote replicas
    // never mutate another peer's authoritative gear, HP or weapon state.
    for(const a of G.actors || [])if(drinkEligible(a,stand,G.time,PLAYER)) {
      stand.taken.add(a); giveDrink(a,G.time,stand.drinkSeconds);
      G.fx?.burst?.(a.pos,new THREE.Vector3(0,1,0),G.teamColors?.[a.team],{count:6,speed:2,size:.08});
    }
    const drinks=stand.mesh?.userData?.drinks;
    if(drinks)for(let j=0;j<drinks.length;j++)drinks[j].visible=j>=Math.min(4,stand.taken.size);
  }
  for(const a of G.actors || []) if(!a.remote) retireDrink(a,G.time);
}

kernels.splash:
if(!p.ghost&&d.splashCount>0&&len>EPS){
  const lifeTravel=travelBefore+p.vel.length()*clamp(p.life-(p.age-DT),0,DT);
  const endTravel=Math.min(s.travel,lifeTravel,travelBefore+len*clamp(Math.min(1,stop)));
  const direction=p.vel.clone().setY(0).normalize();
  while(s.dropCount<d.splashCount&&s.nextSplash<=endTravel+EPS){
    if(stop<=1&&s.nextSplash>=endTravel-EPS)break;
    const from=p.prev.clone().lerp(p.pos,clamp((s.nextSplash-travelBefore)/len));
    const radius=catalogSplashRadius(d,s.dropCount);
    if(d.splashDropSpec||d.sloshFall){
      const drop=spawnSplashDrop(G,{owner:p.owner,team:p.team,seed:p.seed,salt:s.dropCount,
        from,direction,radius,spec:d.splashDropSpec||d.sloshFall.spec,depth:true,
        catchUpSeconds:s.carry,footprint:mainInkFootprint(s.r)});
      if(drop&&d.sloshFall){drop.drawRadius=d.sloshFall.drawRadius;drop.sourceActor=s.r.sourceActor;}
    }else{
      // Geometry-aware nearest/intermediate fallback. Its centre is the
      // exact crossed release coordinate, not the final frame endpoint.
      floorPaint(p.owner,from,radius,d.depth,direction,mainInkFootprint(s.r));
    }
    s.nextSplash+=Math.max(.1,d.splashSpacing);s.dropCount++;
  }
}
